int main(int argc, char **argv)
{
    if (argc < 2) {
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(sz + 1);
    if (!buf) {
        return 1;
    }
    if (sz > 0) {
        fread(buf, 1, sz, f);
    }
    buf[sz] = '\0';
    fclose(f);

    vcardcomponent *comp = vcardcomponent_new_from_string(buf);
    if (comp) {
        vcardcomponent_free(comp);
    }
    free(buf);
    return 0;
}

